// Hellfire: the PlayStation Doom fire, one byte of heat per cell, its spread
// rule in this file's JS and frameos.pixels writing the cells straight into
// the frame (no canvas, no SVG, no markup). The simulation runs at the
// frame's size over pixelSize, so a 480x480 panel at 4 is a 120x120 grid:
// 14,400 cells a frame, about 11 µs each in QuickJS on an ESP32, which is
// why the automatic cell size is 8 there and 4 everywhere else.

// Doom's 37 colors, black to white through the reds and yellows.
const FIRE = [
  0x070707, 0x1f0707, 0x2f0f07, 0x470f07, 0x571707, 0x671f07, 0x771f07, 0x8f2707, 0x9f2f07, 0xaf3f07,
  0xbf4707, 0xc74707, 0xdf4f07, 0xdf5707, 0xdf5707, 0xd75f07, 0xd75f07, 0xd7670f, 0xcf6f0f, 0xcf770f,
  0xcf7f0f, 0xcf8717, 0xc78717, 0xc78f17, 0xc7971f, 0xbf9f1f, 0xbf9f1f, 0xbfa727, 0xbfa727, 0xbfaf2f,
  0xb7af2f, 0xb7b72f, 0xb7b737, 0xcfcf6f, 0xdfdf9f, 0xefefc7, 0xffffff,
]
const PALETTES = {
  fire: FIRE,
  ice: FIRE.map((c) => ((c & 0xff) << 16) | (c & 0xff00) | (c >> 16)),
  toxic: FIRE.map((c) => (((c >> 8) & 0xff) << 16) | (((c >> 16) & 0xff) << 8) | (c & 0xff)),
}
const HOT = FIRE.length - 1

// What outlives a render while the interpreter does. An ESP32 short of
// memory drops the interpreter and the fire restarts from its warm-up.
let heat = null
let cols = 0
let rows = 0
let seed = 1

// One step of the spread. A small LCG: the same seed is the same fire on
// every frame type, which is what makes a snapshot of it stable.
function spread(wind) {
  for (let y = rows - 1; y > 0; y--) {
    const row = y * cols
    const above = row - cols
    for (let x = 0; x < cols; x++) {
      const h = heat[row + x]
      if (h === 0) {
        heat[above + x] = 0
        continue
      }
      seed = (Math.imul(seed, 1664525) + 1013904223) >>> 0
      const r = seed >>> 30 // 0..3
      let dx = x - r + wind
      if (dx < 0) dx += cols
      else if (dx >= cols) dx -= cols
      heat[above + dx] = h - (r & 1)
    }
  }
}

// The frame rate, counted over the last second of renders: what the panel
// really gets, simulation, blit and pacing included.
let fps = null
let frames = 0
let windowStart = 0

function countFrame() {
  const now = Date.now()
  if (!windowStart) windowStart = now
  frames++
  const elapsed = now - windowStart
  if (elapsed >= 1000) {
    fps = Math.round((frames * 1000) / elapsed)
    frames = 0
    windowStart = now
  }
  return fps
}

// The counter, in a 3x5 font, 15 bits a glyph, top row first. It goes into the
// heat for the blit and comes out before the next step: the same cheap write
// as the flames, so it does not slow what it measures, and it never feeds them.
const GLYPHS = {
  0: 0x7b6f, 1: 0x2c97, 2: 0x73e7, 3: 0x73cf, 4: 0x5bc9, 5: 0x79cf, 6: 0x79ef, 7: 0x7249, 8: 0x7bef, 9: 0x7bcf,
  '-': 0x01c0, F: 0x79e4, P: 0x7be4, S: 0x79cf,
}
let label = null
let labelText = ''
let labelScale = 0
let labelled = false
let labelWidth = 0
let labelHeight = 0
let under = null

function setLabel(text, scale) {
  if (text === labelText && scale === labelScale) return
  labelText = text
  labelScale = scale
  labelWidth = (text.length * 4 + 1) * scale
  labelHeight = 7 * scale
  label = new Uint8Array(labelWidth * labelHeight) // 0 is the fire's black
  under = new Uint8Array(labelWidth * labelHeight)
  for (let g = 0; g < text.length; g++) {
    const bits = GLYPHS[text[g]] || 0
    for (let i = 0; i < 15; i++) {
      if (!(bits & (1 << (14 - i)))) continue
      const left = (g * 4 + 1 + (i % 3)) * scale
      const top = (1 + Math.floor(i / 3)) * scale
      for (let y = 0; y < scale; y++) label.fill(HOT, (top + y) * labelWidth + left, (top + y) * labelWidth + left + scale)
    }
  }
}

function labelFits() {
  return labelWidth + labelScale <= cols && labelHeight + labelScale <= rows
}

function labelIn() {
  for (let y = 0; y < labelHeight; y++) {
    const at = (y + labelScale) * cols + labelScale
    under.set(heat.subarray(at, at + labelWidth), y * labelWidth)
    heat.set(label.subarray(y * labelWidth, (y + 1) * labelWidth), at)
  }
}

function labelOut() {
  for (let y = 0; y < labelHeight; y++) {
    heat.set(under.subarray(y * labelWidth, (y + 1) * labelWidth), (y + labelScale) * cols + labelScale)
  }
}

export function get(app, context) {
  if (labelled) labelOut() // the frame before this one has been written
  labelled = false
  const config = app.config
  const asked = Math.round(Number(config.pixelSize) || 0)
  const pixelSize = asked >= 1 ? Math.min(32, asked) : app.frame.embedded ? 8 : 4
  const width = Math.max(pixelSize, context.imageWidth || app.frame.width)
  const height = Math.max(pixelSize, context.imageHeight || app.frame.height)
  const palette = PALETTES[config.palette] || FIRE
  const wind = Math.max(-3, Math.min(3, Math.round(Number(config.wind) || 0)))
  const steps = Math.max(1, Math.min(500, Math.round(Number(config.stepsPerRender) || 1)))
  const w = Math.floor(width / pixelSize)
  const h = Math.floor(height / pixelSize)
  if (!heat || w !== cols || h !== rows) {
    cols = w
    rows = h
    heat = new Uint8Array(cols * rows)
    heat.fill(HOT, (rows - 1) * cols) // the bottom row burns
    const given = Math.round(Number(config.seed) || 0)
    seed = (given > 0 ? given : (Date.now() ^ (Math.random() * 0xffffffff)) >>> 0) || 1
    // Warm up: the flames climb about two rows per heat unit, so by then
    // the first frame is a fire, not a glowing line.
    const climb = Math.min(rows, HOT * 2)
    for (let i = 0; i < climb; i++) spread(wind)
  } else {
    for (let i = 0; i < steps; i++) spread(wind)
  }
  const showFps = config.showFps === true || config.showFps === 'true'
  if (showFps) {
    const rate = countFrame()
    setLabel((rate === null ? '--' : rate) + ' FPS', Math.ceil(4 / pixelSize))
    labelled = labelFits()
    if (labelled) labelIn()
  } else {
    frames = 0
    windowStart = 0
  }
  return frameos.pixels(heat, { width: cols, height: rows, pixelSize, palette })
}
